fn putmask(a: Vec<f32>, mask: Vec<bool>, values: Vec<f32>) -> Vec<f32> {
    // Ensure the replacement array is non-empty (as stated in the problem)
    assert!(!values.is_empty(), "replacement array must be non-empty");
    
    // Create a result vector with the same length as input array
    let mut result = Vec::with_capacity(a.len());
    
    // Iterate through all indices
    for i in 0..a.len() {
        if mask[i] {
            // Use modulo to cycle through replacement values
            let replacement_index = i % values.len();
            result.push(values[replacement_index]);
        } else {
            // Keep the original value
            result.push(a[i]);
        }
    }
    
    result
}